-- 0135_niche_descriptions.sql (2026-07-06)
-- Kolom deskripsi dua-bahasa (konvensi repo: description + description_en) + isi 46 niche.
-- Nada jualan-halus (persetujuan owner). Tampil: teaser tabel tenant, drawer, pencarian.
begin;
alter table niches add column if not exists description text;
alter table niches add column if not exists description_en text;
update niches set description='Sisi gelap sejarah yang tak ditulis di buku pelajaran — rahasia, pengkhianatan, dan kebenaran yang disembunyikan berabad-abad.', description_en='The dark side of history your textbooks skipped — secrets, betrayals, and truths buried for centuries.' where niche_id='dark_history';
