update niches set description='Misteri alam semesta yang membuat penonton merasa kecil dan takjub — lubang hitam, galaksi, dan pertanyaan tanpa jawab.', description_en='Universe mysteries that make viewers feel tiny and awestruck — black holes, galaxies, and questions without answers.' where niche_id='universe_mysteries';
